p=R/'docs/CHARACTER_GENERATION_POLICY.json';d=read(p);d.update(current_stage=state['state'],current_hybrid_output='art/characters/explorer_b_face_animated_v6');d['latest_local_refinement_v6']=state;save(p,d)
p=R/'art/characters/explorer_b_pipeline_v3/pipeline.json';d=read(p);d.setdefault('historical_clean_edges_v5',d.get('current_hybrid_bust',{}));d.update(status=state['state'],current_hybrid_bust=state,current_integrated_face=state);d['current_head_p2'].update(blend=state['blend'],state=state['state'],mouth_rest_prepared=True,eyes_separate=True,rigged=True);save(p,d)
