 res=c.get(state['review_url']);res.raise_for_status();links=set(re.findall(r'(?:src|href|poster)="([^"]+)"',res.text));statuses={x:c.head(state['review_url']+x).status_code for x in links};assert all(v==200 for v in statuses.values());print(state['review_url'],statuses)
